import {featureId,boxRing,facadeEdge,photoSearch,osmLink,commonsLink} from './editor-helpers.mjs';
import {buildingHeight,buildingMinimum,terrainBase} from './buildings.mjs';
import {loadOSM} from './osm-loader.mjs';
import {zoneColor,validPolygon} from './geo.mjs';
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {OBJExporter} from 'three/addons/exporters/OBJExporter.js';
const $=id=>document.getElementById(id),map=L.map('map').setView([55.751,37.618],13);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);let generation=0,downloadedAt=null;let box,features=[],bounds,side,controller,grid=null,scene,renderer,camera,controls;
const overrides=new Map();let selectedId=null,resetCamera=true,pointerStart=null;
function selection(){if(['lat','lon','area'].some(id=>$(id).value.trim()===''))throw Error('Заполните широту, долготу и площадь.');const lat=+$('lat').value,lon=+$('lon').value,a=+$('area').value;if(!Number.isFinite(lat+lon+a)||Math.abs(lat)>80||Math.abs(lon)>180||a<.01||a>4)throw Error('Широта: −80…80; долгота: −180…180; площадь: 0,01…4 км².');side=Math.sqrt(a)*1000;const dy=side/2/111320,dx=dy/Math.cos(lat*Math.PI/180);if(Math.abs(lon)+dx>180)throw Error('Участок не должен пересекать линию смены дат.');return [lat-dy,lon-dx,lat+dy,lon+dx]}
function mark(){clearOverrides();resetCamera=true;generation++;controller?.abort();features=[];bounds=null;grid=null;downloadedAt=null;if(scene)scene.clear();plan();$('load').disabled=false;$('reserve').disabled=false;$('status').textContent='Территория изменена, загрузите данные.';try{const b=selection();if(box)map.removeLayer(box);box=L.rectangle([[b[0],b[1]],[b[2],b[3]]],{color:'#305d42',weight:2}).addTo(map)}catch(e){$('status').textContent=e.message}}
map.on('click',e=>{$('lat').value=e.latlng.lat.toFixed(6);$('lon').value=e.latlng.lng.toFixed(6);mark()});['lat','lon','area'].forEach(id=>$(id).onchange=mark);mark();
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);map.invalidateSize();if(b.dataset.tab==='model')render3d();if(window.innerWidth<=800)document.getElementById(b.dataset.tab).scrollIntoView({behavior:'smooth',block:'start'})});
function polygons(f){return f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[]}
function xy(p){return [(p[0]-bounds[1])/(bounds[3]-bounds[1])*side,(p[1]-bounds[0])/(bounds[2]-bounds[0])*side]}
const building=f=>f.properties.building&&f.properties.building!=='no'&&!f.properties.tainted;
const validPoly=validPolygon;
function minimumHeight(f){return buildingMinimum(f.properties);}
function height(f){return buildingHeight(f.properties);}
function save(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function plan(){const c=$('plan'),ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);if(!bounds)return;const k=1500/side;ctx.save();ctx.beginPath();ctx.rect(50,50,1500,1500);ctx.clip();for(const f of [...features].sort((a,b)=>{const rank=f=>building(f)?3:f.properties.highway?2:f.properties.natural==='water'?1:0;return rank(a)-rank(b)})){const p=f.properties,isB=building(f),green=['wood','grassland','scrub'].includes(p.natural)||['forest','grass','meadow','recreation_ground'].includes(p.landuse)||['park','garden'].includes(p.leisure),water=p.natural==='water'||!!p.water||['reservoir','basin'].includes(p.landuse)||p.waterway==='riverbank',waterline=['river','stream','canal','drain','ditch'].includes(p.waterway);const mode=$('kind').value,zone=zoneColor(p);if(mode==='zones'&&!zone)continue;if(mode==='black'&&!isB||mode==='green'&&!green||mode==='water'&&!water&&!waterline)continue;ctx.fillStyle=isB?'#202d27':green?'#91b987':water?'#a5cbd4':'#e1e3dc';if(mode==='zones')ctx.fillStyle=zone;for(const poly of polygons(f)){if(!validPoly(poly))continue;ctx.beginPath();for(const ring of poly){ring.forEach((p,i)=>{const [x,y]=xy(p);i?ctx.lineTo(50+x*k,1550-y*k):ctx.moveTo(50+x*k,1550-y*k)});ctx.closePath()}ctx.fill('evenodd')}if((mode==='all'&&p.highway||['all','water'].includes(mode)&&waterline)&&f.geometry.type==='LineString'){ctx.strokeStyle=waterline?'#528da8':'#b9b3a7';ctx.lineWidth=3;ctx.beginPath();f.geometry.coordinates.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(50+x*k,1550-y*k):ctx.moveTo(50+x*k,1550-y*k)});ctx.stroke()}}ctx.restore();ctx.fillStyle='#20392f';ctx.font='20px Arial';ctx.fillText('N ↑',1510,35);ctx.fillText(`© OpenStreetMap contributors · ODbL · ${new Date().toISOString().slice(0,10)}`,50,1580);ctx.fillRect(50,25,300,3);ctx.fillText(`${Math.round(side/5)} м`,360,35);ctx.fillText('Центр: '+((bounds[0]+bounds[2])/2).toFixed(5)+', '+((bounds[1]+bounds[3])/2).toFixed(5),600,35);if(['water','all'].includes($('kind').value)){ctx.font='18px Arial';ctx.fillText('Водоёмы — голубая заливка; водотоки — условная линия без достоверной ширины.',50,1725)}if($('kind').value==='zones'){ctx.fillStyle='#fff';ctx.fillRect(50,1610,1500,120);['Жилое|#d9ba80','Коммерция|#db9ea8','Промышленность|#b8a4cd','Зелень / отдых|#91b987','Образование / медицина|#96c4dc'].forEach((v,i)=>{const[t,col]=v.split('|');ctx.fillStyle=col;ctx.fillRect(60+i*290,1630,20,20);ctx.fillStyle='#20392f';ctx.font='16px Arial';ctx.fillText(t,85+i*290,1646)});ctx.fillText('Использование OSM, не юридические зоны ПЗЗ. Белое — нет классификации.',60,1690)}}$('kind').onchange=plan;$('png').onclick=()=>{if(!downloadedAt)return alert('Сначала загрузите данные');$('plan').toBlob(b=>save(b,'atlas-plan.png'))};
async function terrain(signal){const z=13,N=48,cache=new Map();async function sample(lon,lat){const n=2**z,px=(lon+180)/360*n*256,py=(1-Math.asinh(Math.tan(lat*Math.PI/180))/Math.PI)/2*n*256,tx=Math.floor(px/256),ty=Math.floor(py/256),key=tx+'/'+ty;if(!cache.has(key))cache.set(key,(async()=>{const r=await fetch(`https://s3.amazonaws.com/elevation-tiles-prod/terrarium/${z}/${key}.png`,{signal});if(!r.ok)throw Error('DEM HTTP '+r.status);const img=await createImageBitmap(await r.blob()),c=document.createElement('canvas');c.width=c.height=256;const ct=c.getContext('2d');ct.drawImage(img,0,0);img.close();return ct.getImageData(0,0,256,256).data})());const d=await cache.get(key),i=(Math.floor(py%256)*256+Math.floor(px%256))*4;if(d[i+3]!==255)throw Error('DEM содержит отсутствующие значения.');return d[i]*256+d[i+1]+d[i+2]/256-32768}const vals=[];for(let j=0;j<=N;j++){signal.throwIfAborted();for(let i=0;i<=N;i++)vals.push(await sample(bounds[1]+(bounds[3]-bounds[1])*i/N,bounds[0]+(bounds[2]-bounds[0])*j/N))}return {N,vals,min:Math.min(...vals)}}
function elevation(x,y){if(!grid)return 0;const i=Math.max(0,Math.min(grid.N,Math.round(x/side*grid.N))),j=Math.max(0,Math.min(grid.N,Math.round(y/side*grid.N)));return grid.vals[j*(grid.N+1)+i]-grid.min}
function render3d(){if($('model').hidden)return;if(!bounds||!grid){$('modelStats').textContent='Сначала загрузите геоданные и рельеф.';return;}const counts={volumes:0,outlines:0,invalid:0,boundary:0,unknown:0,slopes:0};if(!renderer){renderer=new THREE.WebGLRenderer({antialias:true});$('scene').appendChild(renderer.domElement);camera=new THREE.PerspectiveCamera(45,1,.1,100000);controls=new OrbitControls(camera,renderer.domElement);renderer.domElement.addEventListener('pointerdown',e=>pointerStart=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',pickBuilding);renderer.setAnimationLoop(()=>{const el=$('scene');if(el.clientWidth&&el.clientHeight){renderer.setSize(el.clientWidth,el.clientHeight,false);camera.aspect=el.clientWidth/el.clientHeight;camera.updateProjectionMatrix();controls.update();renderer.render(scene,camera)}})}if(scene)scene.traverse(o=>{o.geometry?.dispose();o.material?.dispose?.()});scene=new THREE.Scene();scene.background=new THREE.Color('#e9ede4');scene.add(new THREE.HemisphereLight(0xffffff,0x557755,3));if(grid){const g=new THREE.PlaneGeometry(side,side,grid.N,grid.N);g.rotateX(-Math.PI/2);const a=g.attributes.position;for(let i=0;i<a.count;i++)a.setY(i,elevation(a.getX(i)+side/2,side/2-a.getZ(i)));g.computeVertexNormals();scene.add(new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:0xa6b89b,side:THREE.DoubleSide})))}for(const f of features.filter(building))for(const poly of polygons(f)){if(!validPoly(poly)){counts.invalid++;continue;}const id=featureId(f),custom=overrides.get(id)||{};let h=custom.height??($('detail').value==='height'||custom.mode?height(f):null);const ring=poly[0];let points=ring.map(xy);if(custom.mode==='box')points=boxRing(points);if(points.some(([x,y])=>x<0||y<0||x>side||y>side)){counts.boundary++;continue;}const elevations=points.map(([x,y])=>elevation(x,y)),base=terrainBase(elevations),rise=Math.max(...elevations)-Math.min(...elevations),minHeight=minimumHeight(f);if(height(f)===null)counts.unknown++;if(minHeight===null||minHeight>=h)h=null;if(h){counts.volumes++;if(rise>2)counts.slopes++;const shape=new THREE.Shape(points.map(([x,y])=>new THREE.Vector2(x-side/2,y-side/2)));for(const hole of (custom.mode==='box'?[]:poly.slice(1)))shape.holes.push(new THREE.Path(hole.map(xy).map(([x,y])=>new THREE.Vector2(x-side/2,y-side/2))));const g=new THREE.ExtrudeGeometry(shape,{depth:h-minHeight,bevelEnabled:false});g.rotateX(-Math.PI/2);g.translate(0,base+minHeight,0);const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:id===selectedId?0xffcf74:custom.mode==='box'?0xffffff:0xe5d9c2}));mesh.userData.buildingId=id;scene.add(mesh);if(custom.texture){const [a,b]=facadeEdge(points,custom.edge||0),dx=b[0]-a[0],dz=-(b[1]-a[1]),w=Math.hypot(dx,dz);if(w>0){const fg=new THREE.PlaneGeometry(w,h-minHeight),fm=new THREE.MeshBasicMaterial({map:custom.texture,side:THREE.DoubleSide,polygonOffset:true,polygonOffsetFactor:-2,polygonOffsetUnits:-2}),face=new THREE.Mesh(fg,fm);face.position.set((a[0]+b[0])/2-side/2,base+minHeight+(h-minHeight)/2,side/2-(a[1]+b[1])/2);face.rotation.y=Math.atan2(-dz,dx);face.userData.buildingId=id;scene.add(face)}}}else{counts.outlines++;for(const contour of poly){const g=new THREE.BufferGeometry().setFromPoints(contour.map(xy).map(([x,y])=>new THREE.Vector3(x-side/2,elevation(x,y)+.5,side/2-y)));const line=new THREE.Line(g,new THREE.LineBasicMaterial({color:id===selectedId?0xff9b00:0x394b40}));line.userData.buildingId=id;scene.add(line)}}}$('modelStats').textContent=`Объёмов: ${counts.volumes}; контуров: ${counts.outlines} (без высоты: ${counts.unknown}); исключено частей: некорректная геометрия ${counts.invalid}, граница участка ${counts.boundary}. Объёмов на склоне: ${counts.slopes}. Основание — средняя отметка DEM, возможны пересечения с рельефом.`;if(resetCamera){camera.position.set(side*.8,side,side);controls.target.set(0,0,0);resetCamera=false;}controls.update()}
$('detail').onchange=render3d;$('obj').onclick=()=>{if(!scene||!grid)return alert('Откройте 3D-модель с загруженным рельефом');save(new Blob([new OBJExporter().parse(scene)],{type:'text/plain'}),'atlas-meters.obj')};
async function loadData(reserve=false){controller?.abort();controller=new AbortController();const signal=controller.signal,job=++generation;$('load').disabled=true;$('reserve').disabled=true;try{bounds=selection();if(reserve&&side*side>1000000)throw Error('Резервная выгрузка доступна для участка до 1 км².');clearOverrides();resetCamera=true;features=[];grid=null;downloadedAt=null;if(scene)scene.clear();plan();$('status').textContent='Загружаем объекты OpenStreetMap…';const result=await loadOSM([...bounds],{signal,...(reserve?{endpoints:['https://api.openstreetmap.org/api/0.6/map.json','https://www.openstreetmap.org/api/0.6/map.json']}:{}),onProgress:message=>{if(job===generation)$('status').textContent=message}});const data=result.data;if(job!==generation)return;features=osmtogeojson(data,{flatProperties:true}).features.filter(f=>!f.properties.tainted);downloadedAt=result.downloadedAt;plan();$('status').textContent='Объекты загружены. Получаем высоты рельефа…';try{const loaded=await terrain(signal);if(job!==generation)return;grid=loaded}catch(e){if(signal.aborted)throw e;$('status').textContent='План доступен. Рельеф недоступен: '+e.message;render3d();return}const bs=features.filter(building);$('status').textContent=`${result.cached?'Из кэша · ':''}Источник: ${new URL(result.endpoint).hostname}.${result.endpoint.endsWith('map.json')?' Резервная выгрузка: протяжённые объекты могут быть неполными.':''} Загружено зданий: ${bs.length}; с тегом height: ${bs.filter(f=>height(f)!==null).length}. DEM z13; сетка 48×48, не геодезическая съёмка. Здания на границе участка в 3D пропускаются.`;render3d()}catch(e){if(job!==generation)return;$('status').textContent='Не удалось загрузить данные: '+e.message}finally{if(job===generation){$('load').disabled=false;$('reserve').disabled=false}}};

$('geojson').onclick=()=>{if(!downloadedAt)return alert('Сначала загрузите данные');save(new Blob([JSON.stringify({type:'FeatureCollection',source:'OpenStreetMap / Overpass, ODbL',downloaded_at:downloadedAt,features},null,2)],{type:'application/geo+json'}),'atlas-source.geojson')};

$('load').onclick=()=>loadData(false);$('reserve').onclick=()=>loadData(true);

function clearOverrides(){for(const v of overrides.values()){v.texture?.dispose();v.bitmap?.close?.();}overrides.clear();selectedId=null;if($('buildingEditor'))$('buildingEditor').hidden=true;}
function currentBuilding(){return features.find(f=>featureId(f)===selectedId);}
function pickBuilding(e){if(!pointerStart||Math.hypot(e.clientX-pointerStart[0],e.clientY-pointerStart[1])>5)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.params.Line.threshold=Math.max(.5,side/180);ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=ray.intersectObjects(scene.children).find(h=>h.object.userData.buildingId);if(!hit)return;selectedId=hit.object.userData.buildingId;showEditor();render3d();}
function showEditor(){const f=currentBuilding();if(!f)return;const c=overrides.get(selectedId)||{};$('buildingEditor').hidden=false;$('buildingTitle').textContent=f.properties.name||selectedId;$('buildingInfo').textContent=`OSM: ${selectedId}. Высота источника: ${height(f)??'не указана'} м. Нижняя отметка: ${minimumHeight(f)??'некорректна'} м. ${c.height?'Используется высота пользователя: '+c.height+' м.':''}`;$('buildingMode').value=c.mode||'footprint';$('userHeight').value=c.height??'';$('facadeEdge').value=(c.edge||0)+1;$('facadePhoto').value='';$('photoSource').value=c.source||'';$('photoCredit').value=c.credit||'';$('photoConfirmed').checked=false;const link=osmLink(selectedId);$('osmBuilding').hidden=!link;if(link)$('osmBuilding').href=link;$('searchBuilding').href=photoSearch(f);$('commonsSearch').href='https://commons.wikimedia.org/w/index.php?title=Special:MediaSearch&type=image&search='+encodeURIComponent(f.properties.name||[f.properties['addr:street'],f.properties['addr:housenumber']].filter(Boolean).join(' ')||selectedId);const commons=commonsLink(f.properties.wikimedia_commons);$('commonsBuilding').hidden=!commons;if(commons)$('commonsBuilding').href=commons;$('photoStatus').textContent=c.texture?'Фото на стороне (не 3D реконструкция). Источник: '+c.source:'Фотография не применена.';}
$('applyBuilding').onclick=()=>{if(!selectedId)return;const raw=$('userHeight').value.trim(),h=raw===''?undefined:Number(raw),edge=Number($('facadeEdge').value)-1;if(h!==undefined&&(!Number.isFinite(h)||h<=0||h>=1000)){alert('Высота должна быть больше 0 и меньше 1000 м.');return;}if(!Number.isInteger(edge)||edge<0){alert('Номер стороны должен быть целым числом от 1.');return;}const c=overrides.get(selectedId)||{};overrides.set(selectedId,{...c,height:h,mode:$('buildingMode').value,edge});render3d();showEditor();};
$('resetBuilding').onclick=()=>{const c=overrides.get(selectedId);c?.texture?.dispose();c?.bitmap?.close?.();overrides.delete(selectedId);render3d();showEditor();};
$('removePhoto').onclick=()=>{const c=overrides.get(selectedId);if(c){c.texture?.dispose();c.bitmap?.close?.();delete c.texture;delete c.bitmap;delete c.source;}render3d();showEditor();};
$('facadePhoto').onchange=async e=>{const file=e.target.files[0],id=selectedId,job=generation;if(!file||!id)return;let source;try{source=new URL($('photoSource').value);if(!['https:','http:'].includes(source.protocol))throw Error();}catch{$('photoStatus').textContent='Укажите ссылку http/https на источник фотографии.';return;}if(!$('photoConfirmed').checked){$('photoStatus').textContent='Подтвердите соответствие фото зданию и стороне.';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){$('photoStatus').textContent='Допустимы JPG/PNG/WebP до 10 МБ.';return;}const f=currentBuilding(),c=overrides.get(id)||{},h=c.height??height(f);if(!h){$('photoStatus').textContent='Для фасада нужна высота OSM или явно введённая высота пользователя.';return;}try{const bitmap=await createImageBitmap(file,{imageOrientation:'flipY',resizeWidth:2048});if(job!==generation||id!==selectedId){bitmap.close();return;}c.texture?.dispose();c.bitmap?.close?.();const texture=new THREE.Texture(bitmap);texture.colorSpace=THREE.SRGBColorSpace;texture.needsUpdate=true;overrides.set(id,{...c,mode:c.mode||'footprint',texture,bitmap,source:source.href,credit:$('photoCredit').value.trim(),edge:Math.max(0,Number($('facadeEdge').value)-1)||0});render3d();showEditor();}catch{$('photoStatus').textContent='Не удалось прочитать изображение.';}};

$('exportSettings').onclick=()=>save(new Blob([JSON.stringify({type:'AtlasBuildingSettings',bounds,source:'OpenStreetMap',overrides:[...overrides].map(([id,c])=>({id,mode:c.mode,height:c.height,heightSource:c.height?'user':'OSM',photoSource:c.source,photoCredit:c.credit,side:(c.edge||0)+1,photoIncluded:false}))},null,2)],{type:'application/json'}),'atlas-building-settings.json');

